MUST_CARRY = ('do not touch production', 'goal:')


def compact_history(client, messages):
    summary = client.summarise(messages)
    return [{'role': 'system', 'content': summary}]


def verify_summary(summary, items=MUST_CARRY):
    missing = [i for i in items if i not in summary]
    if missing:
        raise CompactionRefused(missing)
    return summary


def step(client, messages, budget):
    if tokens(messages) > budget:
        messages = compact_history(client, messages)
        verify_summary(messages[0]['content'])
    return client.respond(messages)
